//! Unicode character properties, with Unicode 18 changes overlaid on the
//! ICU4X 2.1 bundled data.
//!
//! The overlay tables were generated by comparing `icu_properties` 2.1.2 with
//! 2.3.0 plus `icu_properties_data` from unicode-org/icu4x at
//! d1bf2f27ddeabbb61ee50f7cf1dac151aaa0d692 (Unicode 18.0.0).
//! Remove the tables when a released ICU4X data crate contains Unicode 18.

use icu_properties::{
    CodePointMapData, PropertyNamesShort,
    props::{BidiClass, GeneralCategory, Script},
    script::ScriptWithExtensions,
};
use smallvec::SmallVec;
use tinystr::{TinyAsciiStr, tinystr};

pub const VERSION: (u8, u8, u8) = (18, 0, 0);

/// A four-letter ISO 15924 script code, e.g. "Latn"
pub type UnicodeShortName = TinyAsciiStr<4>;

type Range<T> = (u32, u32, T);

fn lookup<T: Copy>(cp: u32, ranges: &'static [Range<T>]) -> Option<T> {
    let index = ranges.partition_point(|(start, _, _)| *start <= cp);
    let (_, end, value) = ranges.get(index.checked_sub(1)?)?;
    (cp <= *end).then_some(*value)
}

