/// The Script property of this code point
pub fn script(cp: u32) -> Option<UnicodeShortName> {
    lookup(cp, SCRIPT)
        .or_else(|| script_short_name(ScriptWithExtensions::new().get_script_val32(cp)))
}

/// The Script_Extensions property of this code point
pub fn script_extensions(cp: u32) -> SmallVec<[UnicodeShortName; 4]> {
    match lookup(cp, SCRIPT_EXTENSIONS) {
        Some(scripts) => scripts.into(),
        None => ScriptWithExtensions::new()
            .get_script_extensions_val32(cp)
            .iter()
            .filter_map(script_short_name)
            .collect(),
    }
}

/// The General_Category property of this character
pub fn general_category(c: char) -> GeneralCategory {
    lookup(c as u32, GENERAL_CATEGORY)
        .unwrap_or_else(|| CodePointMapData::<GeneralCategory>::new().get(c))
}

/// The Bidi_Class property of this code point
pub fn bidi_class(cp: u32) -> BidiClass {
    lookup(cp, BIDI_CLASS).unwrap_or_else(|| CodePointMapData::<BidiClass>::new().get32(cp))
}

/// Whether this is a script added in Unicode 18, unknown to ICU4X 2.1
pub fn is_new_script(script: UnicodeShortName) -> bool {
    matches!(script.as_str(), "Jurc" | "Pcun" | "Seal")
}

/// The four-letter short name of this ICU script
pub fn script_short_name(script: Script) -> Option<UnicodeShortName> {
    PropertyNamesShort::<Script>::new()
        .get(script)
        .and_then(|name| UnicodeShortName::try_from_str(name).ok())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ranges_are_sorted_and_nonoverlapping() {
        fn check<T>(ranges: &[Range<T>]) {
            assert!(
                ranges
                    .windows(2)
                    .all(|window| matches!(window, [first, second] if first.1 < second.0))
            );
        }
        check(SCRIPT);
        check(SCRIPT_EXTENSIONS);
        check(GENERAL_CATEGORY);
        check(BIDI_CLASS);
    }
}
